import{_ as a,o,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const v=JSON.parse('{"title":"Configurar sonidos y voz","description":"","frontmatter":{"title":"Configurar sonidos y voz","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b6be887705d13dfe120f3e07dc4006ec0efa1472b6dbe0ccfc1ebfc1e83f3672","translationRevision":"7fcf8a803f39b330dc6f44c1c88bc560853d923cb3348cc53c36da388e14c7d1","order":20},"headers":[],"relativePath":"es/user/plugins/audio.md","filePath":"es/user/plugins/audio.md","lastUpdated":1794611623000}'),n={name:"es/user/plugins/audio.md"};function r(c,e,t,d,l,u){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="set-up-sounds-and-speech" tabindex="-1">Configurar sonidos y voz <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to &quot;Configurar sonidos y voz {#set-up-sounds-and-speech}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Reproduce un sonido previsible antes de conectarlo a un LIVE concurrido. Necesitas un dispositivo de salida funcional y un archivo de audio compatible. <strong>Play a sound</strong> (<code>audio.play</code>) es una acción integrada; los proveedores de voz, como una integración SonicBoom instalada, requieren configurar su propio plugin y servicio.</p><h2 id="test-a-local-sound" tabindex="-1">Probar un sonido local <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to &quot;Probar un sonido local {#test-a-local-sound}&quot;">​</a></h2><ol><li>En <strong>Automations → Actions</strong>, crea <strong>Play a sound</strong> (<code>audio.play</code>). Selecciona un archivo existente mediante el selector de medios.</li><li>Establece el volumen en <code>0.2</code> para la primera comprobación. El intervalo admitido va de <code>0</code> a <code>1</code>; cero significa silencio.</li><li>Elige la política de solapamiento: <code>allow</code> permite reproducción simultánea, <code>restart</code> reinicia el sonido y <code>drop</code> ignora una nueva instancia mientras ya se reproduce.</li><li>Guarda y lee la configuración antes de pulsar <strong>Test</strong>. La prueba puede producir sonido audible.</li><li>Escucha en el dispositivo previsto. Tras comprobar la reproducción local, vincula la acción a un evento con <a href="./../automations/recipes.html">filtro y espera</a> conservadores.</li></ol><p>La acción conserva una referencia a la ruta del archivo. TikTools no copia el audio a su base de datos. Mantén el archivo en esa ubicación e inclúyelo por separado cuando traslades o respaldes la configuración.</p><h2 id="configure-optional-speech" tabindex="-1">Configurar voz opcional <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to &quot;Configurar voz opcional {#configure-optional-speech}&quot;">​</a></h2><p>Instala el plugin de voz confiable desde <a href="./">Plugins</a>. En sus controles de conexión y ajustes, verifica dirección del servicio, autenticación, proveedor, idioma y voz o perfil. Carga el catálogo antes de probar una frase breve sin datos sensibles. Investiga una voz ausente como posible problema de catálogo, propiedad o proveedor; no inventes su identificador.</p><p>En SonicBoom, la síntesis, la admisión a reproducción y la finalización audible son resultados distintos. Una respuesta en cola o iniciada no demuestra que alguien escuchara la frase. La voz clonada puede tardar más que la llegada de mensajes: revisa diagnósticos de cola y saturación y limita los eventos admitidos.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, estado y recuperación <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, estado y recuperación {#expected-result-status-and-recovery}&quot;">​</a></h2><p>El audio local está disponible cuando el host anuncia su capacidad. La voz depende del plugin instalado y del servicio accesible; esta guía no garantiza aceptación de cada proveedor, dispositivo o plataforma. Si no suena, comprueba archivo, volumen, salida, pausa y error de ejecución. Para voz, verifica servicio y catálogo antes de repetir. Evita pruebas repetidas durante una emisión y consulta <a href="./../preferences/troubleshooting.html">diagnósticos</a> sin compartir tokens ni texto privado hablado.</p>',11)])])}const f=a(n,[["render",r]]);export{v as __pageData,f as default};
